function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  let path
  let options = { headers: { Accept: 'application/json', 'Content-Type': 'application/json' } }
  if (input.operation === 'compare') {
    if (!Array.isArray(input.backtest_ids) || input.backtest_ids.length < 2) throw new Error('backtest_ids must contain two to six ids for compare')
    path = '/api/backtests/compare'
    options = { ...options, method: 'POST', body: JSON.stringify({ ids: input.backtest_ids.map(String) }) }
  } else {
    const id = String(input.backtest_id || '').trim()
    if (!id) throw new Error('backtest_id is required')
    path = '/api/backtests/' + encodeURIComponent(id) + '/' + input.operation
  }
  const response = await fetch(apiOrigin() + path, options)
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  const payload = await response.json()
  if (payload.provenance?.strategy_python?.source) payload.provenance.strategy_python = { sha256: payload.provenance.strategy_python.sha256 }
  return payload
}
